*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
  width: 1280px; height: 800px; overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
  display: flex; align-items: center; justify-content: center;
  color: #fff;
}
body.day { background: linear-gradient(135deg, #1a73e8 0%, #4fc3f7 40%, #81d4fa 100%); }
body.night { background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%); }

.card {
  width: 720px; min-height: 480px;
  background: rgba(255,255,255,0.10);
  backdrop-filter: blur(28px); -webkit-backdrop-filter: blur(28px);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 32px;
  padding: 48px 56px;
  display: flex; flex-direction: column;
  box-shadow: 0 20px 60px rgba(0,0,0,0.35);
}

.header { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 36px; }
.location { font-size: 28px; font-weight: 700; letter-spacing: -0.5px; }
.date { font-size: 17px; opacity: 0.75; font-weight: 500; }

.main-row { display: flex; align-items: center; gap: 48px; margin-bottom: 42px; }
.temps { display: flex; flex-direction: column; }
.temp-high { font-size: 80px; font-weight: 200; line-height: 1; letter-spacing: -3px; }
.temp-low  { font-size: 28px; font-weight: 300; opacity: 0.65; margin-top: 4px; }
.condition-block { display: flex; flex-direction: column; align-items: center; gap: 8px; }
.condition-icon { font-size: 56px; line-height: 1; }
.condition-text { font-size: 18px; font-weight: 500; opacity: 0.85; }

.hourly-wrap { overflow-x: auto; display: flex; gap: 12px; padding-bottom: 4px;
  scrollbar-width: thin; scrollbar-color: rgba(255,255,255,0.2) transparent;
}
.hourly-wrap::-webkit-scrollbar { height: 4px; }
.hourly-wrap::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.2); border-radius: 4px; }

.hour-item {
  flex: 0 0 68px; display: flex; flex-direction: column; align-items: center; gap: 12px;
  padding: 16px 10px; border-radius: 16px;
  background: rgba(255,255,255,0.08);
  transition: background 0.2s;
}
.hour-item:hover { background: rgba(255,255,255,0.16); }
.hour-time { font-size: 13px; font-weight: 600; opacity: 0.7; text-transform: lowercase; }
.hour-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: rgba(255,255,255,0.4);
}
.hour-temp { font-size: 20px; font-weight: 600; }

.error {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 20px; min-height: 360px;
}
.error-icon { font-size: 64px; }
.error-text { font-size: 22px; font-weight: 500; opacity: 0.8; }
.error-detail { font-size: 14px; opacity: 0.5; }

.loading { display: flex; align-items: center; justify-content: center; min-height: 360px; }
.spinner {
  width: 44px; height: 44px; border: 3px solid rgba(255,255,255,0.15);
  border-top-color: rgba(255,255,255,0.7); border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

const WEATHER = {
  0:  { icon:'☀️', text:'Clear sky' },
  1:  { icon:'🌤️', text:'Mainly clear' },
  2:  { icon:'⛅', text:'Partly cloudy' },
  3:  { icon:'☁️', text:'Overcast' },
  45: { icon:'🌫️', text:'Fog' },
  48: { icon:'🌫️', text:'Rime fog' },
  51: { icon:'🌦️', text:'Light drizzle' },
  53: { icon:'🌦️', text:'Moderate drizzle' },
  55: { icon:'🌧️', text:'Dense drizzle' },
  61: { icon:'🌧️', text:'Slight rain' },
  63: { icon:'🌧️', text:'Moderate rain' },
  65: { icon:'🌧️', text:'Heavy rain' },
  71: { icon:'❄️', text:'Slight snow' },
  73: { icon:'❄️', text:'Moderate snow' },
  75: { icon:'❄️', text:'Heavy snow' },
  77: { icon:'🌨️', text:'Snow grains' },
  80: { icon:'🌦️', text:'Slight rain showers' },
  81: { icon:'🌧️', text:'Moderate rain showers' },
  82: { icon:'🌧️', text:'Violent rain showers' },
  85: { icon:'🌨️', text:'Slight snow showers' },
  86: { icon:'🌨️', text:'Heavy snow showers' },
  95: { icon:'⛈️', text:'Thunderstorm' },
  96: { icon:'⛈️', text:'Thunderstorm with slight hail' },
  99: { icon:'⛈️', text:'Thunderstorm with heavy hail' },
};

const params = new URLSearchParams(location.search);
const lat = params.get('lat') || '52.52';
const lon = params.get('lon') || '13.405';
const name = params.get('name') || 'Berlin';
const dateParam = params.get('date');

const today = new Date();
const todayUTC = today.toISOString().slice(0, 10);
const displayDate = dateParam || todayUTC;

function formatDate(iso) {
  const d = new Date(iso + 'T00:00:00Z');
  return d.toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric', timeZone:'UTC' });
}

async function load() {
  const isPast = displayDate < todayUTC;
  const endpoint = isPast ? '/api/om/archive' : '/api/om/forecast';

  const url = new URL(endpoint, location.origin);
  url.searchParams.set('latitude', lat);
  url.searchParams.set('longitude', lon);
  url.searchParams.set('daily', 'temperature_2m_max,temperature_2m_min,weather_code');
  url.searchParams.set('hourly', 'temperature_2m');
  url.searchParams.set('timezone', 'UTC');
  url.searchParams.set('temperature_unit', 'celsius');
  url.searchParams.set('start_date', displayDate);
  url.searchParams.set('end_date', displayDate);

  let resp;
  try {
    resp = await fetch(url);
  } catch (e) {
    renderError('Unable to connect to weather service.');
    return;
  }
  if (!resp.ok) {
    renderError('Weather data could not be loaded.');
    return;
  }
  let data;
  try {
    data = await resp.json();
  } catch (e) {
    renderError('Invalid response from weather service.');
    return;
  }
  if (!data || !data.daily || !data.hourly) {
    renderError('Weather data could not be loaded.');
    return;
  }

  const daily = data.daily;
  const hourly = data.hourly;
  const hi = daily.temperature_2m_max?.[0];
  const lo = daily.temperature_2m_min?.[0];
  const code = daily.weather_code?.[0];
  const w = WEATHER[code] || { icon:'🌈', text:'Unknown' };

  if (hi == null || lo == null) {
    renderError('Weather data could not be loaded.');
    return;
  }

  const hour = new Date().getUTCHours();
  const isDay = code != null ? true : (hour >= 6 && hour < 20);
  document.body.className = isDay ? 'day' : 'night';

  const hours = hourly.time || [];
  const temps = hourly.temperature_2m || [];

  let hourlyHTML = '';
  for (let i = 0; i < hours.length; i++) {
    const h = hours[i].slice(11, 16); // HH:MM
    const t = temps[i] != null ? Math.round(temps[i]) : '—';
    hourlyHTML += '<div class="hour-item"><span class="hour-time">' + h + '</span><span class="hour-dot"></span><span class="hour-temp">' + t + '°</span></div>';
  }

  document.getElementById('card').innerHTML =
    '<div class="header">' +
      '<span class="location">' + h(name) + '</span>' +
      '<span class="date">' + formatDate(displayDate) + '</span>' +
    '</div>' +
    '<div class="main-row">' +
      '<div class="temps">' +
        '<span class="temp-high">' + Math.round(hi) + '°</span>' +
        '<span class="temp-low">L: ' + Math.round(lo) + '°</span>' +
      '</div>' +
      '<div class="condition-block">' +
        '<span class="condition-icon">' + w.icon + '</span>' +
        '<span class="condition-text">' + w.text + '</span>' +
      '</div>' +
    '</div>' +
    '<div class="hourly-wrap">' + hourlyHTML + '</div>';
}

function renderError(msg) {
  document.getElementById('card').innerHTML =
    '<div class="error">' +
      '<span class="error-icon">⚠️</span>' +
      '<span class="error-text">' + h(msg) + '</span>' +
    '</div>';
}

function h(s) {
  const d = document.createElement('div');
  d.appendChild(document.createTextNode(s));
  return d.innerHTML;
}

load();
